/**
 * Icons from Catppuccin for VSCode Icons (MIT, see THIRD_PARTY_NOTICES.md), generated by
 * `scripts/port-catppuccin-icons.mjs` with upstream's colours mapped to the `--icon-*` roles.
 */

/** An SVG element: tag, React props and children. */
export type IconNode = [tag: string, props: Record<string, unknown>, children?: IconNode[]]

type IconSet = {
  /** Lowercase file name, extension (`ts`, `d.ts`) or folder name to icon name. */
  fileNames: Record<string, string>
  fileExtensions: Record<string, string>
  folderNames: Record<string, string>
  icons: Record<string, [viewBox: string, children: IconNode[]]>
}

const [set] = Object.values(
  import.meta.glob<IconSet>('../../assets/icons/catppuccin-icons.json', {
    import: 'default',
    eager: true
  })
)
const { fileNames, fileExtensions, folderNames, icons } = set ?? {
  fileNames: {},
  fileExtensions: {},
  folderNames: {},
  icons: {}
}

export const catppuccinIcon = (name: string): IconSet['icons'][string] | undefined => icons[name]

/** As VS Code matches a file icon theme: the whole name, then the longest extension, then the default. */
export function fileIconName(fileName: string): string {
  const name = fileName.toLowerCase()
  const exact = fileNames[name]
  if (exact) return exact
  for (let dot = name.indexOf('.'); dot !== -1; dot = name.indexOf('.', dot + 1)) {
    const icon = fileExtensions[name.slice(dot + 1)]
    if (icon) return icon
  }
  return '_file'
}

export function folderIconName(folderName: string, open: boolean): string {
  const icon = folderNames[folderName.toLowerCase()] ?? '_folder'
  return open ? `${icon}_open` : icon
}

export const rootIconName = (open: boolean): string => (open ? '_root_open' : '_root')
